begin;
create function pg_temp.expect(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.rejects(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then raise notice 'PASS: %',label;return;end;raise exception 'FAIL: %',label;end $$;
insert into auth.users(id) values('10000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000002'),('10000000-0000-0000-0000-000000000003');
insert into public.chat_profiles(id,display_name,role,must_change_password) values('10000000-0000-0000-0000-000000000001','Teacher','admin',false),('10000000-0000-0000-0000-000000000002','Student','student',false),('10000000-0000-0000-0000-000000000003','Outsider','student',false);
insert into public.chat_classes(id,name) values('20000000-0000-0000-0000-000000000005','Media class');
insert into public.chat_memberships(class_id,user_id) values('20000000-0000-0000-0000-000000000005','10000000-0000-0000-0000-000000000002');
insert into storage.objects(bucket_id,name) values('alnoor-chat-media','20000000-0000-0000-0000-000000000005/10000000-0000-0000-0000-000000000002/test.jpg');
create temp table media_fixture as select jsonb_build_array(jsonb_build_object('kind','image','mime','image/jpeg','size',100,'path','20000000-0000-0000-0000-000000000005/10000000-0000-0000-0000-000000000002/test.jpg')) files;
select pg_temp.expect((select not teacher_voice and not student_voice and not image_upload from public.chat_classes where name='Media class'),'all media disabled by default');
select pg_temp.rejects(format('select public.chat_publish_media(%L,%L,%L,%L::jsonb)','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000005','',(select files from media_fixture)),'disabled images denied at database');
update public.chat_classes set image_upload=true where name='Media class';
select public.chat_publish_media('10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000005','',(select files from media_fixture));
select pg_temp.expect((select body='' and jsonb_array_length(attachments)=1 from public.chat_messages where class_id='20000000-0000-0000-0000-000000000005'),'media-only message keeps file reference');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select pg_temp.expect((select count(*)=1 from storage.objects),'member reads only published class files');
select pg_temp.rejects($q$insert into storage.objects(bucket_id,name) values('alnoor-chat-media','bypass')$q$,'browser cannot bypass backend file validation');
select pg_temp.rejects($q$select public.chat_publish_media('10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000005','x','[]')$q$,'browser cannot call media publish RPC');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select pg_temp.expect((select count(*)=0 from storage.objects),'outsider cannot read Storage files');
reset role;
delete from public.chat_memberships where user_id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select pg_temp.expect((select count(*)=0 from storage.objects),'removed member loses media access with existing token');
reset role;
select pg_temp.rejects(format('select public.chat_publish_media(%L,%L,%L,%L::jsonb)','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000005','',(select files from media_fixture)),'removed member cannot publish');
delete from public.chat_messages where class_id='20000000-0000-0000-0000-000000000005';
select pg_temp.expect((select count(*)=1 from public.chat_media_gc),'history deletion queues physical file cleanup');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select pg_temp.expect((select count(*)=0 from storage.objects),'unreferenced deleted media not readable even by teacher');
reset role;
rollback;
